"""Validate closed-separator ownership even when a surface is unavailable.

This is a semantic check on the unchanged original network, independent of
surface success. Missing members, wrong terminal owners and duplicate Bundle
IDs must never be disguised as an ordinary local geometry failure.
"""
from . import curved_junction_nodes as boundary
from . import curved_patch_provider_nodes as patches
from . import curved_network_ownership_nodes as ownership
from .curved_separator_network_nodes import MAX_SEPARATORS
c = boundary.c


def patch_status_mesh(g, geometry):
    """Normalize record transport without changing owner IDs or validity.

    Providers can carry status in a point-cloud component. Registry lookup uses
    mesh point counts, so retain mesh records and convert point-cloud records
    before applying exactly the same ownership predicates.
    """
    parts = g.node('GeometryNodeSeparateComponents', 'Separate native patch status components')
    g.bind(geometry, parts.inputs['Geometry'])
    vertices = g.node('GeometryNodePointsToVertices', 'Read point-cloud patch status as vertices')
    g.bind(parts.outputs['Point Cloud'], vertices.inputs['Points'])
    return boundary._join(g, parts.outputs['Mesh'], vertices.outputs['Mesh'])


def patch_status_unique(g, geometry):
    """A mixed-component transport cannot introduce repeated owner records."""
    count=ownership._total(g,1,c.named(g,patches.SITE,'INT'))
    return ownership._all(g,geometry,ownership._compare(g,count,1))


def registry(g, inp, original, patch_status, *, free_ends=False, chained=False, free_chains=False, regions=False, direct_sites=False,selection_ends=False, longitudinal_chains=False):
    if longitudinal_chains and not chained:
        raise ValueError('Longitudinal Street membership requires chained separator ownership')
    if selection_ends and not (direct_sites and free_ends):
        raise ValueError('Selection caps need direct, explicit external route ownership')
    if direct_sites and (chained or free_chains or regions):
        raise ValueError('Direct aggregate owners do not use physical chain dispatch')
    if free_chains and not (chained and free_ends):
        raise ValueError('Free chains require both chained and free-ended separator contracts')
    if regions and not (chained and free_ends):
        raise ValueError('Crossing regions require the shared chained and free-ended contracts')
    patch_status = patch_status_mesh(g, patch_status)
    rows = inp.outputs['Separators']; corridors = inp.outputs['Corridors']
    count = c._count(g, rows)
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    names = ('bundle_id', 'member_a', 'member_b', 'head_patch', 'tail_patch')
    if free_ends or chained: names += ('kind',)
    if chained: names += ('a_head','a_tail','b_head','b_tail')
    if free_chains: names += ('a_external','b_external')
    if regions: names += ('tail_a_patch','tail_b_patch','crossing_corridor','crossing_street')
    if selection_ends:names += ('end_role_a','end_role_b','end_section_a','end_section_b')
    valid = ownership._compare(g, count, inp.outputs['Separator Count'])
    valid = valid*patch_status_unique(g,patch_status)
    valid = valid*ownership._compare(g, count, MAX_SEPARATORS, 'LESS_EQUAL')
    valid = valid*ownership._all(g, rows, ownership._exists(g, ['st_sb_'+k for k in names]))
    if chained:
        from . import curved_separator_chain_contract_nodes as chain
        valid = valid*chain.permissions(g, inp, free_chains=free_chains, regions=regions)
    begin = g.node('GeometryNodeRepeatInput', 'Prove every declared separator belongs to its original owners')
    end = g.node('GeometryNodeRepeatOutput'); end.repeat_items.clear()
    if longitudinal_chains:end['st_longitudinal_separator_registry']=1
    end.repeat_items.new('BOOLEAN', 'Valid')
    begin.pair_with_output(end)
    g.bind(valid, begin.inputs['Valid'])
    g.bind(c.choose(g, valid, count, 0, 'INT'), begin.inputs['Iterations'])
    at = begin.outputs['Iteration']
    values = {name: c._read(g, rows, 'st_sb_'+name, at, 'INT') for name in names}
    bid = values['bundle_id']; head = values['head_patch']; tail = values['tail_patch']
    is_free = ownership._compare(g, values['kind'], 1) if free_ends else 0.
    is_chain = ownership._compare(g, values['kind'], 2) if chained else 0.
    is_free_chain = ownership._compare(g, values['kind'], 3) if free_chains else 0.
    is_region = ownership._compare(g, values['kind'], 4) if regions else 0.
    is_selection=ownership._compare(g,values['kind'],5) if selection_ends else 0.
    any_chain = g.math('MAXIMUM', is_chain, is_free_chain)
    any_free = g.math('MAXIMUM', is_free, is_free_chain)
    if regions:
        any_chain = g.math('MAXIMUM',any_chain,is_region)
    indirect_tail = g.math('MAXIMUM',any_free,is_region) if regions else any_free
    if selection_ends:indirect_tail=g.math('MAXIMUM',indirect_tail,is_selection)
    unique = ownership._total(g, 1, c.named(g, 'st_sb_bundle_id', 'INT'))
    ok = ownership._compare(g, c._sample(g, rows, unique, at, 'INT'), 1)
    ok = ok*ownership._compare(g, bid, 0, 'GREATER_EQUAL')
    if free_ends or chained:
        allowed=g.math('MAXIMUM', any_chain, g.math('MAXIMUM', is_free, ownership._compare(g, values['kind'], 0)))
        if selection_ends:allowed=g.math('MAXIMUM',allowed,is_selection)
        ok=ok*allowed
        ok = ok*c.choose(g, indirect_tail, ownership._compare(g, tail, -1), 1.)
    ok = ok*(1.-ownership._compare(g, head, tail))
    ok = ok*(1.-ownership._compare(g, values['member_a'], values['member_b']))
    if selection_ends:
        at_least_one=g.math('MAXIMUM',ownership._compare(g,values['end_role_a'],6),ownership._compare(g,values['end_role_b'],6))
        ok*=c.choose(g,is_selection,at_least_one,1.)
    for endpoint, owner in enumerate((head, tail)):
        if direct_sites:
            sites=inp.outputs['Junctions']
            in_range=ownership._compare(g,owner,0,'GREATER_EQUAL')*ownership._compare(g,owner,c._count(g,sites),'LESS_THAN')
            jid=c._read(g,sites,'st_cj_junction_id',owner,'INT')
            same=ownership._compare(g,c.named(g,'st_cn_owner','INT'),jid)
            found=in_range*ownership._compare(g,c._stat(g,patch_status,same,'Sum'),1)
        else:
            found, _ = patches._lookup(g, patch_status, patches.SITE, owner)
        if endpoint and free_ends: found = c.choose(g, indirect_tail, 1., found)
        ok = ok*found

    def port_owner(port):
        # Junction IDs are compared as integers. Only small array indices are
        # used with Sample Nearest by the registry helpers.
        junction = c._read(g, original, 'st_cj_junction_id', port, 'INT')
        sites = inp.outputs['Junctions']
        match = ownership._compare(g, c.named(g, 'st_cj_junction_id', 'INT'), junction)
        found = ownership._compare(g, c._stat(g, sites, match, 'Sum'), 1)
        site = c._stat(g, sites, match*index, 'Sum')
        if direct_sites:
            return site, found
        second, pair = patches._lookup(g, inp.outputs['Compounds'], 'st_cp_site_b', site)
        owner = c.choose(g, second, c._read(g, inp.outputs['Compounds'], 'st_cp_site_a', pair, 'INT'), site, 'INT')
        logical = c._read(g, original, 'st_cn_logical_owner', port, 'INT')
        clustered = ownership._compare(g, logical, 0, 'GREATER_EQUAL')
        owner = c.choose(g, clustered, c._read(g, inp.outputs['Logical Clusters'], 'st_lg_site', logical, 'INT'), owner, 'INT')
        return owner, found

    for member in ('member_a', 'member_b'):
        match = ownership._compare(g, c.named(g, 'st_cs_street_id', 'INT'), values[member])
        member_ok = ownership._compare(g, c._stat(g, corridors, match, 'Sum'), 1)
        row = c._stat(g, corridors, match*index, 'Sum')
        owners = []
        for end_name in ('start_index', 'end_index'):
            port = c._read(g, corridors, 'st_cs_'+end_name, row, 'INT')
            owner, found = port_owner(port)
            member_ok = member_ok*found
            if direct_sites:
                member_ok=member_ok*ownership._compare(g,c._read(g,original,'st_cj_bundle_id',port,'INT'),bid)
            owners.append(owner)
        forward = ownership._compare(g, owners[0], head)*ownership._compare(g, owners[1], tail)
        reverse = ownership._compare(g, owners[1], head)*ownership._compare(g, owners[0], tail)
        member_ok = member_ok*g.math('MAXIMUM', forward, reverse)
        if free_ends:
            external = inp.outputs['External Approaches']
            match = ownership._compare(g, c.named(g, 'st_ca_street_id', 'INT'), values[member])
            free_ok = ownership._compare(g, c._stat(g, external, match, 'Sum'), 1)
            row = c._stat(g, external, match*index, 'Sum')
            expected_role=1
            if selection_ends:
                side=member[-1];declared=values['end_role_'+side];section=values['end_section_'+side]
                expected_role=c.choose(g,is_selection,declared,1,'INT')
                clipped=ownership._compare(g,declared,6)
                terminal=(ownership._compare(g,declared,1)+clipped)*c.choose(g,clipped,
                    ownership._compare(g,section,0,'GREATER_EQUAL'),ownership._compare(g,section,-1))
                terminal*=ownership._compare(g,c._read(g,external,'st_ca_owner_id',row,'INT'),section)
                terminal*=ownership._compare(g,c._read(g,external,'st_ca_next_section_id',row,'INT'),-1)
                free_ok*=c.choose(g,is_selection,terminal,1.)
            free_ok = free_ok*ownership._compare(g, c._read(g, external, 'st_ca_end_role', row, 'INT'), expected_role)
            port = c._read(g, external, 'st_ca_start_index', row, 'INT')
            owner, found = port_owner(port)
            free_ok = free_ok*found*ownership._compare(g, owner, head)
            if direct_sites:
                free_ok=free_ok*ownership._compare(g,c._read(g,original,'st_cj_bundle_id',port,'INT'),bid)
            member_ok = c.choose(g, g.math('MAXIMUM',is_free,is_selection), free_ok, member_ok)
        ok = ok*c.choose(g, any_chain, 1., member_ok)
    if chained:
        ok = ok*c.choose(g, is_chain, chain.row(g, inp, original, patch_status, values, port_owner, longitudinal_chains=longitudinal_chains), 1.)
    if free_chains:
        from . import curved_free_chain_contract_nodes as free_chain
        ok = ok*c.choose(g, is_free_chain, free_chain.row(g, inp, original, patch_status, values, port_owner, longitudinal_chains=longitudinal_chains), 1.)
    if regions:
        from . import curved_separator_region_contract_nodes as region
        ok = ok*c.choose(g, is_region, region.row(g, inp, original, patch_status, values, port_owner), 1.)
    g.bind(c.V(g, begin.outputs['Valid'])*ok, end.inputs['Valid'])
    return c.V(g, end.outputs['Valid'])
